// Feature flag in ASP.NET Core
builder.Services.AddFeatureManagement()
    .AddFeatureFilter<PercentageFilter>();

app.MapGet("/api/feature", async (IFeatureManagerSnapshot fm) => {
    if (await fm.IsEnabledAsync("NewCheckout")) {
        return Results.Ok(new { flow = "new" });
    }
    return Results.Ok(new { flow = "old" });
});
